          role: '防止副本被减得太少、尾部顶到 Limits：所需副本数 ≥ ⌈P99 总用量 ÷ (Pod Limits × 占比)⌉，与按 Requests 算出的副本数取较大者。结果“风险”里判断峰值是否接近 Limits，也用这条线。',
          scope: '资源大盘的推荐副本数和风险判断，CPU 与内存都适用；Pod 没有 Limits 时不起作用。'
