        sectionOrder: '固定副本数与策略的合并顺序',
        descOrder:
          '固定副本数是把副本数写死成一个常数：不想让算法、预测、指标触发改副本数的工作负载（比如固定 3 副本的有状态服务）填它；填了以后预测模式只管 CPU、内存。它和预测、时间周期、指标触发不是重复的配置，而是合并时“最优先、不再被后面的策略改动”的那一档（只有时间周期里的“固定”和旁路比它更高）。几个策略同时给出不同的副本数时，按下面的顺序合并；最后一步的边界对所有策略生效。',
        orderTitle: '合并顺序',
        order1: '管理员固定的值最优先：旁路、时间周期里“固定”的副本数、上面的固定副本数。之后的策略不改它们。',
        order2: '其余的副本数先由预测得出（预测模式为“不预测”或预测不可用时，用降级默认值）。',
        order3:
          '指标触发策略：设定副本数的取优先级最高的（同级取较大的）；扩容的取增量最大的，它不会被设定、预测或缩容压低；缩容只在没有扩容或设定、没有 OOM 和 JVM 压力、预测不要求更多副本时才生效，多条缩容取减得最少的。',
        order4: '时间周期里“至少”的抬高、“至多”的压低；多个周期按优先级处理。',
