          '一个 Pod 的容量（请求量）里最多用到多少，范围 0.1 到 1，留空或 0 按 1（不保留）。推荐值 = 计算结果 ÷ 容量保留系数：0.8 表示留 20% 的余量，CPU、内存推荐值是（预测峰值 × 推荐值系数）÷ 0.8；动态副本数里单 Pod 的承载 = Pod 请求量 × 该系数。0.8 只是例子，实际读的是这里的值。',
