        fallbackReplicasHint:
          '没有可用的新鲜预测（模型故障、数据不足、推荐过期）时 operator 使用的副本数；不会因它缩容到低于当前值。0 表示不设，冻结当前副本。',
        limitCpuRatio: 'CPU limit 系数',
